import { bigint, doublePrecision, index, integer, jsonb, pgTable, real, text, timestamp } from "drizzle-orm/pg-core"

import type { ElementCategory, ElementLayout } from "@/lib/elements/types"
import type { ExportStatus } from "@/lib/export/types"
import type { ParamDef } from "@/lib/project/schema"
import type { Transcript } from "@/lib/transcript"
import type { MediaKind, ProjectDoc, ProjectFormat } from "@/types/project"

import { user } from "./auth-schema"

// App tables. auth-schema.ts is generated by the Better Auth CLI; keep app tables here.

export const project = pgTable(
  "project",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    format: text("format").$type<ProjectFormat>().notNull(),
    width: integer("width").notNull(),
    height: integer("height").notNull(),
    fps: integer("fps").notNull().default(30),
    durationInFrames: integer("duration_in_frames").notNull(),
    doc: jsonb("doc").$type<ProjectDoc>().notNull(),
    version: integer("version").notNull().default(0),
    thumbnailUrl: text("thumbnail_url"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("project_userId_updatedAt_idx").on(table.userId, table.updatedAt)]
)

/** Files uploaded to ImageKit for a project. */
export const media = pgTable(
  "media",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    projectId: text("project_id")
      .notNull()
      .references(() => project.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    kind: text("kind").$type<MediaKind>().notNull(),
    name: text("name").notNull(),
    mime: text("mime").notNull(),
    size: bigint("size", { mode: "number" }).notNull(),
    imagekitFileId: text("imagekit_file_id").notNull(),
    filePath: text("file_path").notNull(),
    url: text("url").notNull(),
    thumbnailUrl: text("thumbnail_url"),
    width: integer("width"),
    height: integer("height"),
    durationSec: doublePrecision("duration_sec"),
    /** Videos: ~12 frames with timestamps in one image (made in the browser on upload), so Claude can see what's in it. */
    contactSheetUrl: text("contact_sheet_url"),
    /** What's said in it (ImageKit AI transcription, or the user's .srt/.vtt/pasted text), for Claude. */
    transcript: jsonb("transcript").$type<Transcript>(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
  },
  (table) => [index("media_projectId_createdAt_idx").on(table.projectId, table.createdAt)]
)

/** "Mine" elements: code clips the user or Claude saved for reuse. Built-ins live in lib/elements/builtin. */
export const element = pgTable(
  "element",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    category: text("category").$type<ElementCategory>().notNull(),
    /** Where the box goes when it's added (not in the plan's table; needed to place it like the built-ins). */
    layout: text("layout").$type<ElementLayout>().notNull().default("callout"),
    code: text("code").notNull(),
    paramSchema: jsonb("param_schema").$type<ParamDef[]>().notNull(),
    defaultParams: jsonb("default_params").$type<Record<string, unknown>>().notNull(),
    fonts: jsonb("fonts").$type<string[]>().notNull(),
    defaultDurationInFrames: integer("default_duration_in_frames").notNull(),
    createdBy: text("created_by").$type<"user" | "claude">().notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("element_userId_updatedAt_idx").on(table.userId, table.updatedAt)]
)

/** When Claude Code last reached the MCP endpoint for a user (updated on every MCP request). */
export const claudeStatus = pgTable("claude_status", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  lastSeenAt: timestamp("last_seen_at").notNull(),
})

/** A rendered MP4 of a project (see the plan, §9). The render runs as a Trigger.dev task. */
export const videoExport = pgTable(
  "export",
  {
    id: text("id")
      .primaryKey()
      .$defaultFn(() => crypto.randomUUID()),
    projectId: text("project_id")
      .notNull()
      .references(() => project.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    status: text("status").$type<ExportStatus>().notNull().default("queued"),
    /** 0–1 while rendering. */
    progress: real("progress").notNull().default(0),
    triggerRunId: text("trigger_run_id"),
    mp4Url: text("mp4_url"),
    imagekitFileId: text("imagekit_file_id"),
    error: text("error"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    finishedAt: timestamp("finished_at"),
  },
  (table) => [index("export_projectId_createdAt_idx").on(table.projectId, table.createdAt)]
)

/** What the user has open in the editor, so Claude can resolve "this" (see the plan, §8). */
export const editorState = pgTable("editor_state", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  projectId: text("project_id").references(() => project.id, { onDelete: "set null" }),
  selectedClipId: text("selected_clip_id"),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
})
